  await handler.run(job);
  recordJobFinished({ ctx, outcome: "success" });
} catch (error) {
  recordJobFinished({ ctx, outcome: "failure", reason: classifyFailure(error) });
  throw error;
} finally {
  logger.info({ durationMs: monotonicClock.nowMs() - startedAt }, "job finished");
}
```

