```ts
type OrderRow = {
  tenantId: string;
  orderId: string;
  status: OrderStatus;
  total: string;
  placedAt: string;
  fraudScore: number;
  internalNote: string | null;
};

type PublicOrderExportRow = {
  order_id: string;
  status: OrderStatus;
  total: string;
  placed_at: string;
};
```

